import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const T=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-Missing-Values-for-Summary-Variables.md","filePath":"manual-zh/CTABLES-Missing-Values-for-Summary-Variables.md","lastUpdated":1785684581000}'),s={name:"manual-zh/CTABLES-Missing-Values-for-Summary-Variables.md"};function o(i,t,l,c,n,_){return e(),a("div",null,[...t[0]||(t[0]=[r('<h4 id="_15-7-9-2-汇总变量的缺失值" tabindex="-1">15.7.9.2 汇总变量的缺失值 <a class="header-anchor" href="#_15-7-9-2-汇总变量的缺失值" aria-label="Permalink to &quot;15.7.9.2 汇总变量的缺失值&quot;">​</a></h4><p>对于汇总变量，处于所包含类别中的有效取值会被分析，而缺失的或处于被排除类别中的取值不会被分析，但有以下例外：</p><ul><li>“<code>VALIDN</code>”汇总函数（<code>VALIDN</code>、<code>EVALIDN</code>、<code>UVALIDN</code>、<code>_area_ PCT.VALIDN</code> 和 <code>U _area_ PCT.VALIDN</code>）只统计所包含类别中的有效值（不包括所包含类别中的缺失值）。</li><li>“<code>TOTALN</code>”汇总函数（<code>TOTALN</code>、<code>ETOTALN</code>、<code>UTOTALN</code>、<code>_area_ PCT.TOTALN</code>）以及 <code>U _area_ PCT.TOTALN</code> 统计所包含类别中的所有值（有效和缺失）以及被排除类别中的缺失值（不包括有效值）。</li></ul><p>对于分类变量，系统缺失值永远不会处于所包含的类别中。对于标度变量，不存在包含与被排除类别的概念，因此实际上所有值都被包含。</p><p>下表从另一角度展示了上述规则：</p><table tabindex="0"><thead><tr><th></th><th>VALIDN</th><th>other</th><th>TOTALN</th></tr></thead><tbody><tr><td>Categorical variables:</td><td></td><td></td><td></td></tr><tr><td>Valid values in included categories</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td>Missing values in included categories</td><td>—</td><td>yes</td><td>yes</td></tr><tr><td>Missing values in excluded categories</td><td>—</td><td>—</td><td>yes</td></tr><tr><td>Valid values in excluded categories</td><td>—</td><td>—</td><td>—</td></tr><tr><td>Scale variables:</td><td></td><td></td><td></td></tr><tr><td>Valid values</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td>User- or system-missing values</td><td>—</td><td>yes</td><td>yes</td></tr></tbody></table>',6)])])}const m=d(s,[["render",o]]);export{T as __pageData,m as default};
